const qs=[
 "RingHom open immersion descends faithfully flat",
 "RingHom IsOpenImmersion CodescendsAlong FaithfullyFlat",
 "affine open immersion ring hom faithfully flat descent"
];
const rs=[];
for (const q of qs) rs.push(await tools.mcp__lean_lsp__lean_leansearch({query:q,num_results:15}));
rs.forEach((r,i)=>{text(`Q${i+1}`);text(r);});

