const qs=[
 "algebra equivalence B tensor over A A tensor over L K to B tensor over L K scalar tower",
 "tensor product associativity algebra equivalence base change cancellation",
 "(B ⊗[A] (A ⊗[L] K)) ≃ₐ (B ⊗[L] K)"
];
const rs=[];
for (const q of qs) rs.push(await tools.mcp__lean_lsp__lean_leansearch({query:q,num_results:15}));
rs.forEach((r,i)=>{text(`Q${i+1}`); text(r);});

